import yaml
import re

# Load the registry
with open('/home/ubuntu/.agent-ml-research-idea_gen_0509_8/projects/acr-vla-conformal-refinement/registry.yaml', 'r') as f:
    registry = yaml.safe_load(f)

experiments = registry.get('experiments', {})

# Search for experiments with goal/object and vla_only/crm/adaptive with seeds 42/43/44
results = {
    'goal_vla_only': {},
    'goal_crm': {},
    'goal_adaptive': {},
    'object_vla_only': {},
    'object_crm': {},
    'object_adaptive': {}
}

for exp_id, exp_data in experiments.items():
    if not isinstance(exp_data, dict):
        continue

    cmd = exp_data.get('cmd', '')
    hypothesis = exp_data.get('hypothesis', '')
    conclusion = exp_data.get('conclusion', {})
    metrics = conclusion.get('metrics', {}) if isinstance(conclusion, dict) else {}
    success_rate = metrics.get('overall_success_rate', None)

    # Check for benchmark and seed
    if '--benchmark goal' not in cmd and '--benchmark object' not in cmd:
        continue

    benchmark = 'goal' if '--benchmark goal' in cmd else 'object'

    # Extract seed
    seed_match = re.search(r'--seed\s+(\d+)', cmd)
    if not seed_match:
        continue
    seed = seed_match.group(1)

    # Skip if not seed 42, 43, or 44
    if seed not in ['42', '43', '44']:
        continue

    # Determine method (vla_only, crm, adaptive)
    if '--K 1' in cmd and 'vla' in hypothesis.lower() and 'crm' not in hypothesis.lower():
        method = 'vla_only'
    elif 'crm' in hypothesis.lower() or '--K 10' in cmd and 'crm' in hypothesis.lower():
        method = 'crm'
    elif 'adaptive' in hypothesis.lower():
        method = 'adaptive'
    else:
        continue

    key = f'{benchmark}_{method}'
    results[key][f'seed_{seed}'] = {
        'exp_id': exp_id,
        'success_rate': success_rate,
        'cmd': cmd[:120] if cmd else '',
        'hypothesis': hypothesis[:100] if hypothesis else ''
    }

# Print results
for key, entries in results.items():
    if entries:
        print(f"\n{key.upper()}:")
        for seed_key in sorted(entries.keys()):
            entry = entries[seed_key]
            print(f"  {seed_key}: exp_id={entry['exp_id']}, SR={entry['success_rate']}")

