def extract_sr(exp):
    metrics = exp.get('metrics')
    if isinstance(metrics, dict):
        return metrics.get('overall_success_rate')
    return None

# Try variations
goal_vla = ['eval-pi05-vla-only-goal-s42', 'eval-pi05-vla-only-goal-s43', 'eval-pi05-vla-only-goal-s44',
            'eval-goal-vla-only-wrapper-s42', 'eval-goal-vla-only-wrapper-s43', 'eval-goal-vla-only-wrapper-s44']
goal_crm = ['eval-crm-goal-seed42', 'eval-crm-goal-seed43', 'eval-crm-goal-seed44',
            'eval-crm-goal-s42-d149', 'eval-crm-goal-s43-d149', 'eval-crm-goal-s44-d149']
goal_adaptive = ['eval-pi05-adaptive-goal-s42', 'eval-pi05-adaptive-goal-s43', 'eval-pi05-adaptive-goal-s44',
                 'eval-adaptive-goal-s42-d149']

print("Searching for Goal VLA-only:")
found = {}
for exp_id in goal_vla:
    if exp_id in experiments:
        sr = extract_sr(experiments[exp_id])
        if sr is not None:
            found[exp_id] = sr
            print(f"  {exp_id}: {sr}")

if not found:
    # Search by pattern
    for exp_id in experiments:
        if 'goal' in exp_id and 'vla' in exp_id and 'crm' not in exp_id and 'adaptive' not in exp_id:
            if any(s in exp_id for s in ['s42', 's43', 's44', 'seed42', 'seed43', 'seed44']):
                sr = extract_sr(experiments[exp_id])
                if sr is not None:
                    print(f"  {exp_id}: {sr}")

# Alternative: check what's actually in wrapper experiments
